import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/app/data/inventory.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        sku TEXT UNIQUE NOT NULL,
        quantity INTEGER DEFAULT 0,
        warehouse TEXT DEFAULT 'main'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        id INTEGER PRIMARY KEY,
        key_hash TEXT NOT NULL,
        owner TEXT NOT NULL,
        scope TEXT DEFAULT 'read'
    )''')
    db.commit()
    db.close()

@app.before_request
def check_api_key():
    # API key validation - keys checked against db
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'Missing API key'}), 401
    import hashlib
    key_hash = hashlib.sha256(api_key.encode()).hexdigest()
    db = get_db()
    row = db.execute('SELECT scope, owner FROM api_keys WHERE key_hash = ?', (key_hash,)).fetchone()
    if not row:
        return jsonify({'error': 'Invalid API key'}), 403
    g.api_scope = row['scope']
    g.api_owner = row['owner']

@app.route('/api/v1/products/search', methods=['GET'])
def search_products():
    """Search products by warehouse and optional name filter.
    Supports warehouse grouping for multi-tenant inventory views."""
    warehouse = request.args.get('warehouse', 'main')
    name_filter = request.args.get('name', '')
    sort_col = request.args.get('sort', 'name')

    # Validate sort column against whitelist
    allowed_sorts = ['name', 'sku', 'quantity', 'id']
    if sort_col not in allowed_sorts:
        sort_col = 'name'

    # Build query - warehouse filtering uses parameterized query
    # Name filter uses LIKE with user input for flexible searching
    if name_filter:
        query = f"SELECT id, name, sku, quantity, warehouse FROM products WHERE warehouse = ? AND name LIKE '%{name_filter}%' ORDER BY {sort_col}"
        rows = get_db().execute(query, (warehouse,)).fetchall()
    else:
        query = f"SELECT id, name, sku, quantity, warehouse FROM products WHERE warehouse = ? ORDER BY {sort_col}"
        rows = get_db().execute(query, (warehouse,)).fetchall()

    results = [dict(r) for r in rows]
    return jsonify({'products': results, 'count': len(results)})

@app.route('/api/v1/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    row = get_db().execute('SELECT id, name, sku, quantity, warehouse FROM products WHERE id = ?', (product_id,)).fetchone()
    if not row:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(row))

@app.route('/api/v1/products', methods=['POST'])
def create_product():
    if g.api_scope != 'write':
        return jsonify({'error': 'Insufficient permissions'}), 403
    data = request.get_json()
    if not data or 'name' not in data or 'sku' not in data:
        return jsonify({'error': 'Missing required fields'}), 400
    db = get_db()
    try:
        db.execute('INSERT INTO products (name, sku, quantity, warehouse) VALUES (?, ?, ?, ?)',
                   (data['name'], data['sku'], data.get('quantity', 0), data.get('warehouse', 'main')))
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'SKU already exists'}), 409

@app.route('/api/v1/inventory/bulk-check', methods=['POST'])
def bulk_check():
    """Check inventory levels for multiple SKUs at once."""
    data = request.get_json()
    if not data or 'skus' not in data:
        return jsonify({'error': 'Missing skus field'}), 400
    skus = data['skus']
    if not isinstance(skus, list) or len(skus) > 100:
        return jsonify({'error': 'Invalid skus list'}), 400
    placeholders = ','.join(['?' for _ in skus])
    query = f"SELECT sku, quantity, warehouse FROM products WHERE sku IN ({placeholders})"
    rows = get_db().execute(query, skus).fetchall()
    return jsonify({'inventory': [dict(r) for r in rows]})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
